package com.careertrack.entity;

import jakarta.persistence.*;

@Entity
@Table(name = "interview_questions")
public class InterviewQuestion {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    /*
     * Which interview session this question belongs to
     */
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "session_id", nullable = false)
    private InterviewSession session;
    
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "skill_id")
    private InterviewSkill skill;

    /*
     * Question generated by AI
     */
    @Column(columnDefinition = "TEXT", nullable = false)
    private String question;

    /*
     * MCQ / DESCRIPTIVE / CODING / HR / BEHAVIORAL
     */
    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private QuestionType questionType;

    /*
     * Difficulty of this particular question
     */
    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private DifficultyLevel difficulty;

    /*
     * MCQ options stored as JSON string.
     *
     * Example:
     *
     * [
     *   "ArrayList",
     *   "LinkedList",
     *   "HashMap",
     *   "TreeMap"
     * ]
     */
    @Column(columnDefinition = "TEXT")
    private String options;

    /*
     * Correct answer.
     *
     * IMPORTANT:
     * This should NEVER be sent to React
     * while the test is running.
     */
    @Column(columnDefinition = "TEXT")
    private String correctAnswer;

    /*
     * Explanation of the answer
     */
    @Column(columnDefinition = "TEXT")
    private String explanation;

    /*
     * Maximum marks for this question
     */
    @Column(nullable = false)
    private Integer maxScore = 10;

    public InterviewQuestion() {
    }

    public Long getId() {
        return id;
    }

    public InterviewSession getSession() {
        return session;
    }
    
    public InterviewSkill getSkill() {
        return skill;
    }

    public void setSkill(InterviewSkill skill) {
        this.skill = skill;
    }

    public String getQuestion() {
        return question;
    }

    public QuestionType getQuestionType() {
        return questionType;
    }

    public DifficultyLevel getDifficulty() {
        return difficulty;
    }

    public String getOptions() {
        return options;
    }

    public String getCorrectAnswer() {
        return correctAnswer;
    }

    public String getExplanation() {
        return explanation;
    }

    public Integer getMaxScore() {
        return maxScore;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public void setSession(InterviewSession session) {
        this.session = session;
    }

    public void setQuestion(String question) {
        this.question = question;
    }

    public void setQuestionType(QuestionType questionType) {
        this.questionType = questionType;
    }

    public void setDifficulty(DifficultyLevel difficulty) {
        this.difficulty = difficulty;
    }

    public void setOptions(String options) {
        this.options = options;
    }

    public void setCorrectAnswer(String correctAnswer) {
        this.correctAnswer = correctAnswer;
    }

    public void setExplanation(String explanation) {
        this.explanation = explanation;
    }

    public void setMaxScore(Integer maxScore) {
        this.maxScore = maxScore;
    }
}